// MARK: - VaultServices/PendingPasskeyManager.swift
// Processes pending passkeys from the AutoFill extension

import Foundation
import VaultModels
import VaultCrypto
import VaultSync
import VaultAPI
import CryptoKit
import OSLog

private let logger = Logger(subsystem: "com.vaultui", category: "PendingPasskeyManager")

/// Processes pending FIDO2 passkeys generated by the AutoFill extension.
public enum PendingPasskeyManager {
    @MainActor private static var lastUnsupportedCredentialIdsNotificationKey: String?

    /// Backfill required FIDO2 fields that older builds may have omitted.
    @discardableResult
    public static func repairPasskeyCompatibility(syncEngine: SyncEngine, vaultKey: SymmetricCryptoKey) async -> Bool {
        do {
            let modified = try await MainActor.run {
                let persistedCiphers = try syncEngine.fetchCiphers(includeDeleted: false)
                var modifiedCipherCount = 0
                var modifiedPasskeyCount = 0
                var modifiedCipherIds = [String]()
                var unsupportedCredentialIds = Set<String>()

                for persisted in persistedCiphers {
                    var cipher = try persisted.toCipher()
                    guard var loginData = cipher.login,
                          var fido2List = loginData.fido2Credentials,
                          !fido2List.isEmpty else { continue }

                    let encryptionKey = itemEncryptionKey(for: cipher, vaultKey: vaultKey)
                    var changedPasskeys = 0

                    for index in fido2List.indices {
                        if try applyFido2CompatibilityDefaults(
                            to: &fido2List[index],
                            encryptionKey: encryptionKey,
                            fallbackCreationDate: cipher.creationDate ?? cipher.revisionDate ?? Date()
                        ) {
                            changedPasskeys += 1
                        }
                        if hasUnsupportedCredentialId(fido2List[index], encryptionKey: encryptionKey) {
                            unsupportedCredentialIds.insert(unsupportedCredentialIdKey(cipherId: persisted.id, fido2: fido2List[index], encryptionKey: encryptionKey))
                        }
                    }

                    guard changedPasskeys > 0 else { continue }

                    loginData.fido2Credentials = fido2List
                    cipher.login = loginData
                    try syncEngine.saveCipherLocally(cipher, operation: .update)
                    modifiedCipherCount += 1
                    modifiedPasskeyCount += changedPasskeys
                    modifiedCipherIds.append(persisted.id)
                }

                return (modifiedCipherCount, modifiedPasskeyCount, modifiedCipherIds, unsupportedCredentialIds)
            }

            if !modified.3.isEmpty {
                logger.warning("Found \(modified.3.count) active passkey(s) with non-GUID credential IDs that cannot be safely rewritten")
                await notifyUnsupportedCredentialIdsIfNeeded(passkeyCount: modified.3.count, keys: modified.3)
            }

            if modified.0 > 0 {
                logger.info("Repaired FIDO2 compatibility fields on \(modified.1) passkey(s) across \(modified.0) cipher(s)")
                do {
                    try await syncEngine.fullSync()
                    let unsyncedIds = try await MainActor.run {
                        let modifiedIds = Set(modified.2)
                        return try syncEngine.fetchCiphers(includeDeleted: false)
                            .filter { modifiedIds.contains($0.id) }
                            .filter { $0.syncStatus != .synced || $0.pendingOperation != nil }
                            .map(\.id)
                    }

                    if unsyncedIds.isEmpty {
                        logger.info("Synced repaired FIDO2 compatibility fields to server")
                        notifyRepairSynced(cipherCount: modified.0, passkeyCount: modified.1)
                    } else {
                        logger.error("Failed to sync repaired FIDO2 compatibility fields for cipher(s): \(unsyncedIds.joined(separator: ","), privacy: .public)")
                        notifyRepairSyncFailed(cipherCount: modified.0, passkeyCount: modified.1)
                        return false
                    }
                } catch {
                    logger.error("Failed to sync repaired FIDO2 compatibility fields: \(error.localizedDescription)")
                    notifyRepairSyncFailed(cipherCount: modified.0, passkeyCount: modified.1)
                    return false
                }
            }
            return true
        } catch {
            logger.error("Failed to repair FIDO2 compatibility fields: \(error.localizedDescription)")
            return false
        }
    }

    private static func notifyRepairSynced(cipherCount: Int, passkeyCount: Int) {
        let passkeyLabel = passkeyCount == 1 ? "passkey" : "passkeys"
        let itemLabel = cipherCount == 1 ? "item" : "items"
        VaultNotificationCenter.notify(
            title: "Passkeys repaired",
            body: "Repaired \(passkeyCount) \(passkeyLabel) in \(cipherCount) \(itemLabel) and synced them to the server."
        )
    }

    private static func notifyRepairSyncFailed(cipherCount: Int, passkeyCount: Int) {
        let passkeyLabel = passkeyCount == 1 ? "passkey" : "passkeys"
        let itemLabel = cipherCount == 1 ? "item" : "items"
        VaultNotificationCenter.notify(
            title: "Passkey repair needs sync",
            body: "Repaired \(passkeyCount) \(passkeyLabel) in \(cipherCount) \(itemLabel), but the server update did not complete."
        )
    }

    @MainActor
    private static func notifyUnsupportedCredentialIdsIfNeeded(passkeyCount: Int, keys: Set<String>) {
        let notificationKey = keys.sorted().joined(separator: "|")
        guard notificationKey != lastUnsupportedCredentialIdsNotificationKey else {
            return
        }
        lastUnsupportedCredentialIdsNotificationKey = notificationKey

        let passkeyLabel = passkeyCount == 1 ? "passkey" : "passkeys"
        VaultNotificationCenter.notify(
            title: "Passkeys need re-registration",
            body: "\(passkeyCount) active \(passkeyLabel) use older non-GUID credential IDs and cannot be safely migrated for Bitwarden iOS."
        )
    }
    
    /// Processes all pending passkeys from the shared keychain.
    ///
    /// - Parameters:
    ///   - syncEngine: SyncEngine to read/write local vault items
    ///   - vaultKey: Decrypted vault symmetric key for encryption
    public static func processPendingPasskeys(syncEngine: SyncEngine, vaultKey: SymmetricCryptoKey) async {
        let store = SharedCredentialStore.shared
        let pendingList = store.fetchPendingPasskeys()
        
        guard !pendingList.isEmpty else {
            return
        }
        
        logger.info("Processing \(pendingList.count) pending passkeys from AutoFill extension")
        
        var hasErrors = false
        var modifiedCiphers = false
        var modifiedLiveCiphers = false
        var processedCredentialIds = Set<String>()
        var processedRegistrationKeys = Set<String>()
        
        for pending in pendingList {
            do {
                // Determine user name
                let userName = pending.userName ?? pending.relyingPartyId
                let userHandleBase64 = pending.userHandle.base64URLEncodedString()
                let rpName = pending.relyingPartyId
                let credentialIdBase64 = pending.credentialId.bitwardenFido2CredentialId()
                let privateKeyBase64 = pending.privateKeyBase64

                guard processedCredentialIds.insert(credentialIdBase64).inserted else {
                    logger.info("Skipping duplicate pending passkey for \(pending.relyingPartyId)")
                    continue
                }

                let registrationKey = pendingRegistrationKey(for: pending)
                guard processedRegistrationKeys.insert(registrationKey).inserted else {
                    logger.info("Skipping duplicate pending registration for \(pending.relyingPartyId)")
                    continue
                }
                
                let allCiphers: [(cipher: Cipher, syncStatus: SyncStatus)] = await MainActor.run {
                    guard let persisted = try? syncEngine.fetchCiphers() else { return [] }
                    return persisted.compactMap { item in
                        guard let cipher = try? item.toCipher() else { return nil }
                        return (cipher, item.syncStatus)
                    }
                }

                if allCiphers.contains(where: {
                    cipherContainsPasskey($0.cipher, credentialIdBase64: credentialIdBase64, vaultKey: vaultKey)
                }) {
                    logger.info("Skipping already-saved passkey for \(pending.relyingPartyId)")
                    continue
                }

                let targetEntry: (cipher: Cipher, syncStatus: SyncStatus)? = {
                    guard let targetId = pending.targetCipherId,
                          let existingPersisted = allCiphers.first(where: { $0.cipher.id == targetId }) else { return nil }
                    return existingPersisted
                }()
                let targetCipher = targetEntry?.cipher
                
                let encryptionKey: SymmetricCryptoKey
                if let itemKeyEnc = targetCipher?.key,
                   let itemKeyData = try? CipherEncryption.decryptData(itemKeyEnc, key: vaultKey),
                   let itemKey = try? SymmetricCryptoKey(keyData: itemKeyData) {
                    encryptionKey = itemKey
                } else {
                    encryptionKey = vaultKey
                }
                
                // Construct the Fido2Credential with encrypted fields
                var fido2 = Fido2Credential()
                fido2.rpId = try CipherEncryption.encrypt(string: pending.relyingPartyId, key: encryptionKey)
                fido2.rpName = try CipherEncryption.encrypt(string: rpName, key: encryptionKey)
                fido2.userName = try CipherEncryption.encrypt(string: userName, key: encryptionKey)
                fido2.userDisplayName = try CipherEncryption.encrypt(string: userName, key: encryptionKey)
                fido2.userHandle = try CipherEncryption.encrypt(string: userHandleBase64, key: encryptionKey)
                
                fido2.credentialId = try CipherEncryption.encrypt(string: credentialIdBase64, key: encryptionKey)
                fido2.keyType = try CipherEncryption.encrypt(string: "public-key", key: encryptionKey)
                fido2.keyAlgorithm = try CipherEncryption.encrypt(string: "ECDSA", key: encryptionKey)
                fido2.keyCurve = try CipherEncryption.encrypt(string: "P-256", key: encryptionKey)
                fido2.keyValue = try CipherEncryption.encrypt(string: privateKeyBase64, key: encryptionKey)
                fido2.discoverable = try CipherEncryption.encrypt(string: "true", key: encryptionKey)
                fido2.counter = try CipherEncryption.encrypt(string: "0", key: encryptionKey)
                fido2.creationDate = pending.creationDate
                
                var cipher: Cipher
                let operation: PendingOperation
                
                if let existingCipher = targetCipher {
                    
                    // Assign to existing cipher
                    cipher = existingCipher
                    var loginData = cipher.login ?? LoginData()
                    var fido2List = loginData.fido2Credentials ?? []
                    fido2List.append(fido2)
                    loginData.fido2Credentials = fido2List
                    cipher.login = loginData
                    operation = .update
                } else {
                    // Create new cipher
                    cipher = Cipher(type: .login)
                    let newName = pending.targetCipherName ?? "Passkey: \(pending.relyingPartyId)"
                    cipher.name = try CipherEncryption.encrypt(string: newName, key: vaultKey)
                    
                    var loginData = LoginData()
                    loginData.fido2Credentials = [fido2]
                    
                    let uri = LoginUri(uri: try CipherEncryption.encrypt(string: pending.relyingPartyId, key: vaultKey), match: .domain)
                    loginData.uris = [uri]
                    
                    if let user = pending.userName {
                        loginData.username = try CipherEncryption.encrypt(string: user, key: vaultKey)
                    }
                    
                    cipher.login = loginData
                    operation = .create
                }
                
                // Save locally and sync
                let targetIsTemporary = targetEntry?.syncStatus == .temporaryDraft
                try await MainActor.run {
                    if targetIsTemporary {
                        try syncEngine.saveTemporaryCipherLocally(cipher)
                    } else {
                        try syncEngine.saveCipherLocally(cipher, operation: operation)
                    }
                }
                modifiedCiphers = true
                if !targetIsTemporary {
                    modifiedLiveCiphers = true
                }
                
            } catch {
                logger.error("Failed to process pending passkey for \(pending.relyingPartyId): \(error.localizedDescription)")
                hasErrors = true
            }
        }
        
        if !hasErrors {
            store.clearPendingPasskeys()
            logger.info("Successfully processed all pending passkeys and cleared the queue")
            // Export to SharedCredentialStore immediately so the AutoFill extension sees it
            await MainActor.run {
                SharedCredentialStore.shared.exportCredentials(from: syncEngine, vaultKey: vaultKey)
            }
            
            // Trigger a sync to push to server
            if modifiedLiveCiphers {
                try? await syncEngine.fullSync()
            }
        } else {
            logger.warning("Some pending passkeys failed to process; queue not cleared")
        }
    }

    private static func pendingRegistrationKey(for pending: PendingPasskey) -> String {
        [
            pending.targetCipherId ?? "",
            pending.targetCipherName ?? "",
            pending.relyingPartyId,
            pending.userHandle.base64EncodedString(),
            pending.userName ?? "",
        ].joined(separator: "\u{1F}")
    }

    private static func cipherContainsPasskey(
        _ cipher: Cipher,
        credentialIdBase64: String,
        vaultKey: SymmetricCryptoKey
    ) -> Bool {
        guard let fido2List = cipher.login?.fido2Credentials, !fido2List.isEmpty else {
            return false
        }

        let encryptionKey = itemEncryptionKey(for: cipher, vaultKey: vaultKey)
        return fido2List.contains { fido2 in
            guard let encryptedCredentialId = fido2.credentialId,
                  let existingCredentialId = try? CipherEncryption.decryptString(encryptedCredentialId, key: encryptionKey) else {
                return false
            }
            return existingCredentialId == credentialIdBase64
        }
    }

    private static func itemEncryptionKey(for cipher: Cipher, vaultKey: SymmetricCryptoKey) -> SymmetricCryptoKey {
        if let itemKeyEnc = cipher.key,
           let itemKeyData = try? CipherEncryption.decryptData(itemKeyEnc, key: vaultKey),
           let itemKey = try? SymmetricCryptoKey(keyData: itemKeyData) {
            return itemKey
        }
        return vaultKey
    }

    private static func applyFido2CompatibilityDefaults(
        to fido2: inout Fido2Credential,
        encryptionKey: SymmetricCryptoKey,
        fallbackCreationDate: Date
    ) throws -> Bool {
        var changed = false

        func setEncryptedDefault(_ keyPath: WritableKeyPath<Fido2Credential, EncString?>, _ value: String) throws {
            guard fido2[keyPath: keyPath] == nil else { return }
            fido2[keyPath: keyPath] = try CipherEncryption.encrypt(string: value, key: encryptionKey)
            changed = true
        }

        func normalizeEncryptedValue(
            _ keyPath: WritableKeyPath<Fido2Credential, EncString?>,
            transform: (String) -> String?
        ) throws {
            guard let encryptedValue = fido2[keyPath: keyPath],
                  let currentValue = try? CipherEncryption.decryptString(encryptedValue, key: encryptionKey),
                  let normalizedValue = transform(currentValue),
                  normalizedValue != currentValue else { return }
            fido2[keyPath: keyPath] = try CipherEncryption.encrypt(string: normalizedValue, key: encryptionKey)
            changed = true
        }

        func normalizeUserHandle() throws {
            guard let credentialId = fido2.credentialId,
                  let credentialIdValue = try? CipherEncryption.decryptString(credentialId, key: encryptionKey),
                  let credentialIdData = Data(bitwardenFido2CredentialId: normalizeCredentialId(credentialIdValue) ?? credentialIdValue) else {
                return
            }

            let fallbackUserHandle = credentialIdData.base64URLEncodedString()

            guard let userHandle = fido2.userHandle else {
                fido2.userHandle = try CipherEncryption.encrypt(string: fallbackUserHandle, key: encryptionKey)
                changed = true
                return
            }

            guard let userHandleValue = try? CipherEncryption.decryptString(userHandle, key: encryptionKey) else {
                return
            }
            guard userHandleValue.isEmpty || Data(base64URLDecoded: userHandleValue) == nil else {
                return
            }

            fido2.userHandle = try CipherEncryption.encrypt(string: fallbackUserHandle, key: encryptionKey)
            changed = true
        }

        try normalizeEncryptedValue(\.credentialId, transform: normalizeCredentialId)
        try normalizeEncryptedValue(\.keyValue, transform: normalizeKeyValue)
        try normalizeUserHandle()

        try setEncryptedDefault(\.keyType, "public-key")
        try setEncryptedDefault(\.keyAlgorithm, "ECDSA")
        try setEncryptedDefault(\.keyCurve, "P-256")
        try setEncryptedDefault(\.discoverable, "true")
        try setEncryptedDefault(\.counter, "0")

        try normalizeEncryptedValue(\.keyType) { $0 == "2" ? "public-key" : $0 }
        try normalizeEncryptedValue(\.keyAlgorithm) { $0 == "-7" ? "ECDSA" : $0 }
        try normalizeEncryptedValue(\.keyCurve) { $0 == "1" ? "P-256" : $0 }

        if fido2.creationDate == nil {
            fido2.creationDate = fallbackCreationDate
            changed = true
        }

        if fido2.rpName == nil, let rpId = fido2.rpId {
            fido2.rpName = rpId
            changed = true
        }
        if fido2.userDisplayName == nil, let userName = fido2.userName {
            fido2.userDisplayName = userName
            changed = true
        }

        return changed
    }

    private static func normalizeCredentialId(_ value: String) -> String? {
        if UUID(uuidString: value) != nil {
            return value
        }

        let rawValue = value.hasPrefix("b64.") ? String(value.dropFirst(4)) : value
        guard let decoded = Data(base64URLDecoded: rawValue) ?? Data(base64Encoded: rawValue) else {
            return nil
        }
        return decoded.bitwardenFido2CredentialId()
    }

    private static func hasUnsupportedCredentialId(
        _ fido2: Fido2Credential,
        encryptionKey: SymmetricCryptoKey
    ) -> Bool {
        guard let credentialId = fido2.credentialId,
              let value = try? CipherEncryption.decryptString(credentialId, key: encryptionKey),
              let data = Data(bitwardenFido2CredentialId: value) else {
            return false
        }
        return data.count != 16
    }

    private static func unsupportedCredentialIdKey(
        cipherId: String,
        fido2: Fido2Credential,
        encryptionKey: SymmetricCryptoKey
    ) -> String {
        let credentialId = fido2.credentialId.flatMap { try? CipherEncryption.decryptString($0, key: encryptionKey) } ?? ""
        let rpId = fido2.rpId.flatMap { try? CipherEncryption.decryptString($0, key: encryptionKey) } ?? ""
        return "\(cipherId)|\(rpId)|\(credentialId)"
    }

    private static func normalizeKeyValue(_ value: String) -> String? {
        guard let keyData = Data(base64URLDecoded: value) ?? Data(base64Encoded: value) else {
            return nil
        }

        if keyData.count == 32,
           let privateKey = try? P256.Signing.PrivateKey(rawRepresentation: keyData) {
            return privateKey.derRepresentation.base64URLEncodedString()
        }

        return value
    }
}
